class Solution:
    def containsDuplicate(self, nums: list[int]) -> bool:
        seen: set[int] = set()
        for i, x in enumerate(nums):
            if x in seen:  # viz:check
                return True  # viz:found
            seen.add(x)  # viz:store
        return False  # viz:done
